def lucas_number(n):
    if n == 0:
        return 2
    if n == 1:
        return 1
    a, b = 2, 1
    for _ in range(2, n + 1):
        a, b = b, a + b
    return b

L_100 = lucas_number(100)
print(f"L_100 has {len(str(L_100))} digits.")
print(f"L_100 value (first 20 digits): {str(L_100)[:20]}...")

def fibonacci(n):
    if n <= 0:
        return 0
    elif n == 1:
        return 1
    else:
        a, b = 0, 1
        for _ in range(2, n + 1):
            a, b = b, a + b
        return b

F_values = {}
for k in range(2, 21):
    F_values[k] = fibonacci(k)

print("F_k for k=2 to k=20:")
for k, Fk in F_values.items():
    print(f"F_{k} = {Fk}")

D = list(F_values.values())
print(f"\nDifferences D = {D}")
print(f"Number of required differences m = {len(D)}")

